  @state BOX_PAD = 3  @ 178
  @state DROP_ARROW = ' \xe2\x96\xbe'  @ 233
  @state pickerOpenReq = nil  @ 274   -- kind name; consumed by next drawPicker(kind)
  @state pickerOpenSeed = nil  @ 275   -- initial filter text for a request-driven open (type-to-open)
  @state lastToolbarRects = {}  @ 279
  @state toolbarWidths = {}  @ 281
      @invariant  one page draws per frame; cleared at next toolbar() start — no cross-page collision.  @ 280
  @state toolbarLines = 1  @ 282   -- wrapped-row count from the last toolbar() draw
  @state resetPending = false  @ 283
  @state pickerFilter, pickerCursor = {}, {}  @ 411
  @state pickerDeleting = {}  @ 412   -- per kind: the row key whose delete button has been clicked once
  @state pickerActive = false  @ 413   -- frame-scoped: any picker popup live this frame
  @state clearSelCb = nil  @ 416
  @state CREATE = {}  @ 423
  @state DEL_GLYPH = 9  @ 457   -- px across the drawn ×
  @state PALETTE_W, PANE_GAP = 200, 11  @ 643
  @state HEADER_PAD, HEADER_GAP = 8, 4  @ 644
  @state TREE_INDENT, ARROW_GUTTER = 12, 14  @ 742
  @state CHIP_OPEN, CHIP_SHUT = '\xe2\x96\xbe', '\xe2\x96\xb8'  @ 743

# Private functions
  @fn resolve(key)  @ 21-40
      @contract  walks colour aliases (see docs/configManager.md) to a terminal atom; outermost alpha override wins; cycles raise with the resolved chain  @ 20
  @fn scopedKey(name, scope)  @ 46-51
  @fn compactControl(draw)  @ 159-166
      -- Compact (zero-padding) control — checkbox / radio — vertically centered in the
      -- ambient framed-row height; measured from GetFrameHeight, not a fixed nudge.
  @fn setCollapsed(id, on)  @ 292-296
      -- A segment with a summary is collapsible; folded ids persist in config.
  @fn disclosureHeading(text, collapsed)  @ 300-313
      -- headingLabel that toggles: a leading triangle discloses the folded state.
      -- ▸/▾ advance differently, so the triangle gets a fixed cell — no 1px heading shift.
  @fn drawSegment(seg, collapsed)  @ 315-327
  -- Picker (typeahead popup, shared across pages)
  @fn deleteRowButton(kind, key, id, rowLeft, rowW)  @ 461-489
      -- The '?' slot is always reserved, so arming never shifts the ×. Placement has two gotchas
      -- (SameLine's offset base, the Selectable's extended rect) -- see docs/chrome.md § Picker.
  -- Palette pane (shared right-hand pane: arrange / wiring / tracker / sampler)
  @fn paletteTabsHeader(tabs, activeKey, onTab)  @ 671-694
      -- Tabbed header: equal-width cells, active in text ink, rest dimmed (palette.tabInactive).
      -- Dividers run the full header height with a bottom gap; a click fires onTab(key).
  @fn fitLabel(text, maxW)  @ 718-727
      -- Ellipsis-fit to a fixed pane width; no horizontal scroll exists. Private: the
      -- trees fit their own labels, and no caller outside chrome has wanted it.

# Public API (chrome.*)
  @api chrome.colour(name, scope)  @ 53-60
  @api chrome.screenPainter()  @ 67
      -- Identity-transform painter over the current window's draw list: screen coords, chrome's
      -- palette. Build one per draw fn — the draw list is captured now, so call it in the target window.
  @api chrome.pushChromeStyles()  @ 69-103
  @api chrome.popChromeStyles()  @ 105-108
  @api chrome.pushChromeWindow()  @ 111-120
      -- Floating surfaces fill with editor.bg (opaque); toolbar.bg is 0.5 alpha and would bleed the grid through.
  @api chrome.popChromeWindow()  @ 122-126
  @api chrome.verticalSeparator()  @ 130-136
      -- reaper-imgui has no Separator(Vertical); draw a 1px vertical rule via the window draw
      -- list and reserve a Dummy slot so SameLine works. see docs/chrome.md § Vertical separator
  @api chrome.disabledIf(cond, fn)  @ 140-144
      -- RAII wrapper for ImGui.BeginDisabled / EndDisabled: dropping the
      -- bracket-match removes a class of mismatched-pop bugs on early return.
  @api chrome.row(h, fn)  @ 148-155
      -- Fixed-height row: run `fn`, then snap the cursor to exactly `h` below the row's
      -- top so subsequent rows land at a deterministic Y regardless of widget heights.
  @api chrome.checkbox(label, value)  @ 168-170
  @api chrome.radio(label, active)  @ 172-174
  @api chrome.numberStepper(id, value, opts)  @ 179-229
  @api chrome.dropdown(id, current, items)  @ 234-259
  @api chrome.headingLabel(text)  @ 263-270
      -- Section label for toolbar segments: bold + uppercase + dimmed so it
      -- reads as a heading and not a control. Caller follows with SameLine.
  @api chrome.resetToolbar()  @ 286
      -- Deferred: the switcher lives in the toolbar, so setActive fires mid-render — clearing
      -- now would unwrap this frame's later segments. Clear at the next toolbar() start instead.
  @api chrome.toolbarRects()  @ 288
  @api chrome.toolbarLineCount()  @ 289
  @api chrome.makeToolbar()  @ 329-405
  @api chrome.requestPickerOpen(kind, seed)  @ 418
  @api chrome.pickerIsActive()  @ 419
  @api chrome.resetPickerActive()  @ 420
  @api chrome.libPicker(key, current, excludeOthers)  @ 427-453
      -- Build the picker-item list for a library-shaped cm key (e.g. 'swings',
      -- 'tempers'); groups, modified badge, excludeOthers — see docs/chrome.md § Picker.
  @api chrome.drawPicker(d)  @ 493-637
      -- Generic typeahead picker. Enter picks the highlighted match; group
      -- separators show only when filter is empty.
  @api chrome.gridWidth(w)  @ 647
      @contract  width of the main pane left of the palette; floors at 120.  @ 646
  @api chrome.paletteHeader(label)  @ 651-667
      -- Hand-drawn header: centred label + 1px divider at headerH; shares HEADER_PAD/HEADER_GAP
      -- with the flanking grid header so dividers align across PANE_GAP. Returns divider screen-y.
  @api chrome.palettePane(spec)  @ 697-714
      @contract  x/y/h are body-window screen coords at the gap's left edge; draw paints the body.  @ 696
  @api chrome.rowSelectable(label, selected, flags)  @ 731-738
      -- Selectable with hover/active highlight suppressed: only the selected row shows
      -- the Col_Header fill. Shared by the tracker palette and the sampler browser/tree.
  @api chrome.treeRow(opts)  @ 750-777
      -- One tree row, sampler-tree style: a draw-list chip in a fixed gutter (never
      -- highlighted), then a selectable label; the row owns its nesting indent.
      @contract  chip toggles; body click selects and toggles a parent; allowDouble suppresses both  @ 747
      @contract  childless rows show blank gutter so labels align across depths  @ 748
      @contract  nesting indent = opts.indent (px) if set, else depth × TREE_INDENT  @ 749
  @api chrome.treeHeading(opts)  @ 781-786
      -- Non-selectable tree heading (fx-section labels, group dividers): a dimmed label.
      @contract  gutter=true aligns text with a same-depth row label, not its chip; else flush indent  @ 780

